from pathlib import Path

path = Path('/home/ubuntu/alfurqan-school-management/client/src/pages/Home.tsx')
source = path.read_text()
old = '''const pageSize = 25; const input = useMemo(() => ({ page, pageSize, search: query || undefined, role: roleFilter }), [page, query, roleFilter]); const { data, isLoading } = trpc.school.staffPage.useQuery(input); const exportInput = useMemo(() => ({ search: query || undefined, role: roleFilter }), [query, roleFilter]); const { data: exportRows = [] } = trpc.school.staff.useQuery(exportInput); const profileInput = useMemo(() => ({ id: selected ?? 0 }), [selected]); const profile = trpc.school.staffProfile.useQuery(profileInput, { enabled: selected !== null }); const rows = data?.rows ?? [];'''
new = '''const pageSize = 25; const staffDirectoryRows = (accountsQuery.data ?? []).filter(account => account.accountStatus !== "deleted").map(account => ({ id: account.id, name: account.name ?? "Unnamed staff account", staffRole: account.role === "admin" ? "Administrator" : account.role === "principal" ? "Principal" : account.role === "accountant" ? "Accountant" : "Teacher", department: account.role === "accountant" ? "Finance" : account.role === "teacher" ? "Teaching" : "Administration", phone: account.phone ?? "—", email: account.email ?? "—", status: account.accountStatus, staffNo: account.username ?? `STAFF-${account.id}`, linkedStudentId: account.linkedStudentId })); const filteredDirectoryRows = staffDirectoryRows.filter(row => (roleFilter === "All roles" || row.staffRole === roleFilter) && (!query.trim() || `${row.name} ${row.staffRole} ${row.department} ${row.phone} ${row.email}`.toLowerCase().includes(query.trim().toLowerCase()))); const totalPages = Math.max(1, Math.ceil(filteredDirectoryRows.length / pageSize)); const rows = filteredDirectoryRows.slice((page - 1) * pageSize, page * pageSize); const exportRows = filteredDirectoryRows; const selectedAccount = staffDirectoryRows.find(row => row.id === selected) ?? null; const isLoading = accountsQuery.isLoading;'''
if old not in source:
    raise SystemExit('staff directory query block not found')
source = source.replace(old, new, 1)
source = source.replace('data?.total ?? 0} total records', 'filteredDirectoryRows.length} total records', 1)
source = source.replace('Math.max(1, data?.totalPages ?? 1)', 'totalPages', 1)
source = source.replace('disabled={page >= (data?.totalPages ?? 1)}', 'disabled={page >= totalPages}', 1)
source = source.replace('profile.data?.staff.name ?? "Loading..."', 'selectedAccount?.name ?? "Staff account"', 1)
source = source.replace('{profile.data && <><div className="profile-grid"><div><span className="muted">Staff no.</span><b>{profile.data.staff.staffNo}</b></div><div><span className="muted">Role</span><b>{profile.data.staff.staffRole}</b></div><div><span className="muted">Department</span><b>{profile.data.staff.department}</b></div><div><span className="muted">Phone</span><b>{profile.data.staff.phone}</b></div><div><span className="muted">Email</span><b>{profile.data.staff.email}</b></div><div><span className="muted">Status</span><b>{profile.data.staff.status}</b></div></div><h4>Related staff records</h4><div className="module-list">{profile.data.relatedRecords.map(record => <div className="module-row" key={record.label}><div><b>{record.label}</b><p>{record.detail}</p></div></div>)}</div></>}', '{selectedAccount && <><div className="profile-grid"><div><span className="muted">Staff no.</span><b>{selectedAccount.staffNo}</b></div><div><span className="muted">Role</span><b>{selectedAccount.staffRole}</b></div><div><span className="muted">Department</span><b>{selectedAccount.department}</b></div><div><span className="muted">Phone</span><b>{selectedAccount.phone}</b></div><div><span className="muted">Email</span><b>{selectedAccount.email}</b></div><div><span className="muted">Status</span><b>{selectedAccount.status}</b></div></div><h4>Account scope</h4><p className="muted">This staff directory is sourced from the administrator-managed portal account and excludes student and subject accounts.</p></>}', 1)
path.write_text(source)
print('Staff directory now uses staff accounts')
